function texto(valor) {
  return String(valor ?? '').trim();
}

function removerDecimaisZero(valor) {
  return valor.replace(
    /\b(\d+)\.0+\b/g,
    '$1'
  );
}

function removerAcentos(valor) {
  return texto(valor)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function escaparOData(valor) {
  return texto(valor).replace(/'/g, "''");
}

function aplicarMapaPorPalavra(valor, mapa) {
  let resultado = valor;

  const termos = Object.keys(mapa)
    .sort((a, b) => b.length - a.length);

  for (const termo of termos) {
    const substituto = mapa[termo];

    const termoEscapado = termo.replace(
      /[.*+?^${}()|[\]\\]/g,
      '\\$&'
    );

    resultado = resultado.replace(
      new RegExp(`\\b${termoEscapado}\\b`, 'g'),
      substituto
    );
  }

  return resultado;
}

function removerPalavras(valor, palavras) {
  let resultado = valor;

  for (const palavra of palavras) {
    resultado = resultado.replace(
      new RegExp(`\\b${palavra}\\b`, 'g'),
      ' '
    );
  }

  return resultado;
}

function limparEspacos(valor) {
  return texto(valor)
    .replace(/\s+/g, ' ')
    .trim();
}

/* -------------------------------------------------------------------------- */
/* Dicionários                                                                */
/* -------------------------------------------------------------------------- */

const sinonimosGlobais = {
  PÇ: 'UN',
  PC: 'UN',
  PCA: 'UN',
  PECA: 'UN',
  UND: 'UN',
  UNID: 'UN',
  UNIDADE: 'UN',

  METRO: 'M',
  METROS: 'M',

  QTD: 'QUANTIDADE',

  ELETR: 'ELETRICO',
  ELET: 'ELETRICO',

  TRIF: 'TRIFASICO',
  MONOF: 'MONOFASICO',

  EXT: 'EXTERNO',
  INT: 'INTERNO'
};

const sinonimosPorFamilia = {
  CABOS: {
    CU: 'COBRE',
    COB: 'COBRE',
    AL: 'ALUMINIO',
    ALUM: 'ALUMINIO',

    FLEX: 'FLEXIVEL',
    FLEXIV: 'FLEXIVEL',

    RIG: 'RIGIDO',

    COND: 'CONDUTOR',

    XLPE: 'XLPE',
    EPR: 'EPR',
    PVC: 'PVC'
  },

  DISJUNTORES: {
    DISJ: 'DISJUNTOR',
    DJ: 'DISJUNTOR',

    MONOP: 'MONOPOLAR',
    UNIP: 'MONOPOLAR',
    UNIPOLAR: 'MONOPOLAR',

    BIP: 'BIPOLAR',
    '2P': 'BIPOLAR',

    TRIP: 'TRIPOLAR',
    '3P': 'TRIPOLAR',

    TETRAP: 'TETRAPOLAR',
    '4P': 'TETRAPOLAR',

    CM: 'CAIXA MOLDADA',
    MCCB: 'CAIXA MOLDADA',
    MCB: 'MINIDISJUNTOR'
  },

  ELETRODUTOS: {
    ELETROD: 'ELETRODUTO',
    ELETRODUTO: 'ELETRODUTO',

    CORR: 'CORRUGADO',

    GALV: 'GALVANIZADO',

    PEAD: 'PEAD',
    PVC: 'PVC'
  },

  POSTES: {
    CONC: 'CONCRETO',

    DT: 'DUPLO T',
    DUPLOT: 'DUPLO T',

    CIRC: 'CIRCULAR'
  },

  TRANSFORMADORES: {
    TRAFO: 'TRANSFORMADOR',
    TRANSF: 'TRANSFORMADOR',

    OLEO: 'OLEO',
    SECO: 'SECO'
  },

  CONECTORES: {
    CONECT: 'CONECTOR',
    CONEC: 'CONECTOR',

    PERF: 'PERFURANTE',

    COMP: 'COMPRESSAO'
  },

  TERMINAIS: {
    TERM: 'TERMINAL',

    COMP: 'COMPRESSAO'
  },

  ISOLADORES: {
    ISOL: 'ISOLADOR',

    POLIM: 'POLIMERICO',

    PORC: 'PORCELANA'
  },

  BARRAMENTOS: {
    BARR: 'BARRAMENTO',

    CU: 'COBRE',
    AL: 'ALUMINIO'
  }
};

/*
 * Removemos apenas palavras de ligação.
 * Não remover “TIPO”, “CLASSE”, “CURVA”, “EXTERNO” ou “INTERNO”,
 * pois podem diferenciar materiais.
 */
const palavrasLigacao = [
  'DE',
  'DA',
  'DO',
  'DAS',
  'DOS',
  'EM',
  'PARA'
];

/* -------------------------------------------------------------------------- */
/* Identificação de família                                                   */
/* -------------------------------------------------------------------------- */

function identificarFamilia(valor) {
  const descricao = limparEspacos(valor);

  if (
    /\bCABO\b/.test(descricao) ||
    /\bCONDUTOR\b/.test(descricao)
  ) {
    return 'CABOS';
  }

  if (
    /\bDISJUNTOR\b/.test(descricao) ||
    /\bDISJ\b/.test(descricao) ||
    /\bMCCB\b/.test(descricao) ||
    /\bMCB\b/.test(descricao)
  ) {
    return 'DISJUNTORES';
  }

  if (
    /\bELETRODUTO\b/.test(descricao) ||
    /\bELETROD\b/.test(descricao)
  ) {
    return 'ELETRODUTOS';
  }

  if (/\bPOSTE\b/.test(descricao)) {
    return 'POSTES';
  }

  if (
    /\bTRANSFORMADOR\b/.test(descricao) ||
    /\bTRAFO\b/.test(descricao) ||
    /\bTRANSF\b/.test(descricao)
  ) {
    return 'TRANSFORMADORES';
  }

  if (/\bCONECTOR\b|\bCONECT\b|\bCONEC\b/.test(descricao)) {
    return 'CONECTORES';
  }

  if (/\bTERMINAL\b|\bTERM\b/.test(descricao)) {
    return 'TERMINAIS';
  }

  if (/\bISOLADOR\b|\bISOL\b/.test(descricao)) {
    return 'ISOLADORES';
  }

  if (/\bBARRAMENTO\b|\bBARR\b/.test(descricao)) {
    return 'BARRAMENTOS';
  }

  if (
    /\bCHAVE SECCIONADORA\b/.test(descricao) ||
    /\bSECCIONADORA\b/.test(descricao)
  ) {
    return 'CHAVES_SECCIONADORAS';
  }

  if (
    /\bCAIXA PASSAGEM\b/.test(descricao) ||
    /\bCAIXA DE PASSAGEM\b/.test(descricao)
  ) {
    return 'CAIXAS_PASSAGEM';
  }

  return 'OUTROS';
}

/* -------------------------------------------------------------------------- */
/* Padronização técnica                                                       */
/* -------------------------------------------------------------------------- */

function padronizarUnidades(valor) {
  let resultado = valor;

  // Seção de condutor
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*MM\s*[²2]\b/g, '$1 MM2')
    .replace(/(\d+(?:[.,]\d+)?)\s*MM2\b/g, '$1 MM2')
    .replace(/(\d+(?:[.,]\d+)?)\s*MMQ\b/g, '$1 MM2');

  // Diâmetro e dimensões lineares
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*MM\b/g, '$1 MM')
    .replace(/(\d+(?:[.,]\d+)?)\s*CM\b/g, '$1 CM')
    .replace(/(\d+(?:[.,]\d+)?)\s*M\b/g, '$1 M');

  // Corrente
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*AMPERES?\b/g, '$1 A')
    .replace(/(\d+(?:[.,]\d+)?)\s*AMP\b/g, '$1 A')
    .replace(/(\d+(?:[.,]\d+)?)\s*A\b/g, '$1 A');

  // Tensão
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*KV\b/g, '$1 KV')
    .replace(/(\d+(?:[.,]\d+)?)\s*V\b/g, '$1 V');

  // Potência ativa, aparente e reativa
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*KVAR\b/g, '$1 KVAR')
    .replace(/(\d+(?:[.,]\d+)?)\s*KVA\b/g, '$1 KVA')
    .replace(/(\d+(?:[.,]\d+)?)\s*MVA\b/g, '$1 MVA')
    .replace(/(\d+(?:[.,]\d+)?)\s*KW\b/g, '$1 KW')
    .replace(/(\d+(?:[.,]\d+)?)\s*MW\b/g, '$1 MW');

// Força / carga mecânica
resultado = resultado
  .replace(/(\d+(?:[.,]\d+)?)\s*DAN\b/g, '$1 DAN');

  // Capacidade de interrupção
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*KA\b/g, '$1 KA');

  // Potência mecânica
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*CV\b/g, '$1 CV')
    .replace(/(\d+(?:[.,]\d+)?)\s*HP\b/g, '$1 HP');

  return resultado;
}

function padronizarNumeros(valor) {
  return valor.replace(
    /(\d),(\d)/g,
    '$1.$2'
  );
}

function padronizarTensoesDeCabo(valor, familia) {
  if (familia !== 'CABOS') {
    return valor;
  }

  let resultado = valor;

  /*
   * Normaliza somente equivalências explicitamente
   * informadas na descrição.
   * Não completa classes de tensão ausentes.
   */
  resultado = resultado
    .replace(
      /\b0[.,]6\s*[\/\\-]\s*1\s*KV\b/g,
      '0.6/1 KV'
    )
    .replace(
      /\b0\s+6\s+1\s+KV\b/g,
      '0.6/1 KV'
    )
    .replace(
      /\b600\s*[\/\\-]\s*1000\s*V\b/g,
      '0.6/1 KV'
    )
    .replace(
      /\b450\s*[\/\\-]\s*750\s*V\b/g,
      '450/750 V'
    );

  return resultado;
}

function padronizarPolos(valor, familia) {
  if (familia !== 'DISJUNTORES') {
    return valor;
  }

  return valor
    .replace(/\b1\s*P\b/g, 'MONOPOLAR')
    .replace(/\b2\s*P\b/g, 'BIPOLAR')
    .replace(/\b3\s*P\b/g, 'TRIPOLAR')
    .replace(/\b4\s*P\b/g, 'TETRAPOLAR');
}

function padronizarDimensoes(valor) {
  return valor
    .replace(
      /(\d+(?:\.\d+)?)\s*[X×]\s*(\d+(?:\.\d+)?)\s*MM\b/g,
      '$1 X $2 MM'
    )
    .replace(
      /(\d+(?:\.\d+)?)\s*[X×]\s*(\d+(?:\.\d+)?)\s*[X×]\s*(\d+(?:\.\d+)?)\s*MM\b/g,
      '$1 X $2 X $3 MM'
    );
}

/* -------------------------------------------------------------------------- */
/* Geração das chaves                                                         */
/* -------------------------------------------------------------------------- */

function normalizarDescricao(valor) {
  let resultado = removerAcentos(valor)
    .toUpperCase()
    .replace(/²/g, '2')
    .replace(/[“”"'`´]/g, ' ')
    .replace(/[(){}\[\]]/g, ' ')
    .replace(/[;:]/g, ' ')
    .replace(/–|—/g, '-');

  resultado = limparEspacos(resultado);

  const familia = identificarFamilia(resultado);

  resultado = aplicarMapaPorPalavra(
    resultado,
    sinonimosGlobais
  );

  const regrasFamilia =
    sinonimosPorFamilia[familia] || {};

  resultado = aplicarMapaPorPalavra(
    resultado,
    regrasFamilia
  );

  resultado = padronizarNumeros(resultado);
  resultado = padronizarUnidades(resultado);
  // Remove apenas casas decimais zero após separar/padronizar unidades.
  resultado = removerDecimaisZero(resultado);
  resultado = padronizarTensoesDeCabo(
    resultado,
    familia
  );
  resultado = padronizarPolos(
    resultado,
    familia
  );
  resultado = padronizarDimensoes(resultado);

  /*
   * Preserva "/" em tensões como 0.6/1 KV e códigos como 12/600.
   * Preserva "." para valores decimais.
   */
  resultado = resultado
    .replace(/[^A-Z0-9./]+/g, ' ');

  resultado = removerPalavras(
    resultado,
    palavrasLigacao
  );

  resultado = limparEspacos(resultado);

  return {
    descricao_normalizada: resultado,
    familia
  };
}


function normalizarSap(valor) {
  const codigo = String(valor ?? '').trim();
  return codigo && codigo !== '0' ? codigo : '';
}

return $input.all().map((item, index) => {
  const row = item.json || {};
  const codigoNeoenergia = normalizarSap(row.codigo_neoenergia);
  const descricao = texto(row.descricao || row.Material || row.Title);
  const normalizado = descricao ? normalizarDescricao(descricao) : { descricao_normalizada: '', familia: 'OUTROS' };
  const nomeNormalizado = texto(row.nome_normalizado) || normalizado.descricao_normalizada;

  return {
    json: {
      ...row,
      catalogo_item_id: row.catalogo_item_id ? Number(row.catalogo_item_id) : null,
      codigo_neoenergia: codigoNeoenergia,
      codigo_neoenergia_odata: escaparOData(codigoNeoenergia),
      descricao,
      nome_normalizado: nomeNormalizado,
      categoria: normalizado.familia,
      familia: texto(row.familia || row.categoria),
      fonte: texto(row.fonte),
      possui_sap_valido: Boolean(codigoNeoenergia),
      revisao_material_oficial: codigoNeoenergia ? null : 'SEM_SAP_VALIDO'
    },
    pairedItem: { item: item.pairedItem?.item ?? index }
  };
});

const entrada = $('PREP - Identidade Material Oficial').item.json;
const encontrados = Array.isArray($json.value) ? $json.value : [];
if (encontrados.length !== 1) throw new Error(`Esperado 1 Material Oficial para o SAP ${entrada.codigo_neoenergia}; encontrados: ${encontrados.length}`);
return { json: { ...entrada, material_oficial_id: Number(encontrados[0].id), material_oficial_origem: 'EXISTENTE' } };

const entrada = $('PREP - Identidade Material Oficial').item.json;
const id = Number($json.id);
if (!id) throw new Error(`POST não retornou ID para o SAP ${entrada.codigo_neoenergia}`);
return { json: { ...entrada, material_oficial_id: id, material_oficial_origem: 'CRIADO' } };
